"use strict";

// Worker for the two-process persistence test. Its only stored values are dummy
// markers generated by the fixture; no Discord account or real token is used.
const { app, BrowserWindow, session } = require("electron");
const fs = require("node:fs");
const path = require("node:path");
const assert = require("node:assert/strict");
const phase = process.argv.find(value => value.startsWith("--phase="))?.slice(8);
const dataPath = process.argv.find(value => value.startsWith("--profile="))?.slice(10);
assert(dataPath && ["write", "read"].includes(phase));
const setPath = app.setPath.bind(app);
app.setPath = (name, value) => setPath(name, name === "userData" ? dataPath : value);
app.getVersion = () => require("../package.json").version;
app.setPath("userData", dataPath);
fs.mkdirSync(dataPath, { recursive: true });
fs.writeFileSync(path.join(dataPath, "channels.json"), "[]");
require("../src/irc-main");

async function until(check) {
  for (let attempt = 0; attempt < 100; attempt++) {
    if (await check()) return;
    await new Promise(resolve => setTimeout(resolve, 50));
  }
  throw new Error("Persistence fixture did not become ready");
}

app.whenReady().then(async () => {
  try {
    const isolated = session.fromPartition("persist:idle-chats-discord-secondary");
    assert.equal(isolated.isPersistent(), true);
    assert(path.resolve(isolated.getStoragePath()).startsWith(path.resolve(dataPath) + path.sep));
    isolated.protocol.handle("https", () => new Response(`<!doctype html><title>Persistence fixture</title>
      <script>
        window.savedOnOpen = localStorage.getItem('idlechats-session-test');
        window.exitCountOnOpen = Number(localStorage.getItem('idlechats-exit-count') || 0);
        addEventListener('beforeunload', () => {
          localStorage.setItem('idlechats-session-test', 'saved-by-page-exit');
          localStorage.setItem('idlechats-exit-count', String(window.exitCountOnOpen + 1));
          document.cookie = 'idlechats_session_test=retained;path=/;max-age=86400;SameSite=Lax;Secure';
        });
      </script><p>Dummy persisted session</p>`, { headers: { "content-type": "text/html; charset=utf-8" } }));
    await until(() => BrowserWindow.getAllWindows().length);
    const main = BrowserWindow.getAllWindows()[0];
    await until(() => main.webContents.executeJavaScript("Boolean(window.idleChats)"));
    const open = async () => {
      await main.webContents.executeJavaScript('window.idleChats.discordAction("open")');
      const panel = BrowserWindow.getAllWindows().find(window => window !== main);
      const contents = panel.contentView.children.find(view => view.webContents && view.webContents !== panel.webContents).webContents;
      await until(() => contents.executeJavaScript("typeof window.savedOnOpen !== 'undefined'"));
      return contents;
    };
    let contents = await open();
    if (phase === "write") {
      assert.equal(await contents.executeJavaScript("window.savedOnOpen"), null);
      await main.webContents.executeJavaScript('window.idleChats.discordAction("stop")');
      contents = await open();
      assert.equal(await contents.executeJavaScript("window.savedOnOpen"), "saved-by-page-exit");
      assert.equal(await contents.executeJavaScript("window.exitCountOnOpen"), 1);
      await main.webContents.executeJavaScript('window.idleChats.discordAction("hide")');
      console.log("PASS: Encerrar/reopen preserves page-exit storage; quitting with Discord hidden.");
    } else {
      assert.equal(await contents.executeJavaScript("window.savedOnOpen"), "saved-by-page-exit");
      assert.equal(await contents.executeJavaScript("window.exitCountOnOpen"), 2);
      const cookies = await isolated.cookies.get({ url: "https://discord.com", name: "idlechats_session_test" });
      assert.equal(cookies.length, 1);
      assert.equal(cookies[0].value, "retained");
      console.log("PASS: a new app process restored DOM storage and cookies from the previous normal app exit.");
    }
    // Exercise the real application's asynchronous before-quit handler.
    app.quit();
  } catch (error) { console.error(error); app.exit(1); }
});
setTimeout(() => { console.error("Persistence worker timed out"); app.exit(2); }, 20_000).unref();
